long long power(long long b, long long e) {
    long long r = 1; b %= MOD;
    while (e > 0) {
        if (e & 1) r = r * b % MOD;     // this bit of e is set
        b = b * b % MOD;                // b, b^2, b^4, b^8...
        e >>= 1;
    }
    return r;
}
long long inv(long long a) { return power(a, MOD - 2); }

vector<bool> sieve(int n) {          // is[i] true if i is prime
    vector<bool> is(n + 1, true);
    is[0] = is[1] = false;
    for (long long i = 2; i * i <= n; i++)
        if (is[i])
            for (long long j = i * i; j <= n; j += i)
                is[j] = false;
    return is;
}
